 3	final class InsertionSortAlgorithm implements IntArraySortAlgorithm {
 4	
 5	    static final InsertionSortAlgorithm INSTANCE = new InsertionSortAlgorithm();
 6	
 7	    private InsertionSortAlgorithm() {
 8	        // Utility class.
 9	    }
10	
11	    @Override
12	    public void sort(IntArraySlice slice) {
13	        if (slice.hasFewerThanTwoElements()) {
14	            return;
15	        }
16	
17	        for (int currentIndex = slice.startInclusive() + 1;
18	                currentIndex < slice.endExclusive();
19	                currentIndex++) {
20	            insertValue(slice, currentIndex);
21	        }
22	    }
23	
24	    @Override
25	    public boolean isSorted(IntArraySlice slice) {
26	        for (int index = slice.startInclusive() + 1; index < slice.endExclusive(); index++) {
27	            if (slice.valueAt(index - 1) > slice.valueAt(index)) {
28	                return false;
29	            }
30	        }
31	
32	        return true;
33	    }
34	
35	    private static void insertValue(IntArraySlice slice, int currentIndex) {
36	        int valueToInsert = slice.valueAt(currentIndex);
37	        int insertionIndex = findInsertionIndex(slice, currentIndex, valueToInsert);
38	
39	        slice.shiftRight(insertionIndex, currentIndex);
40	        slice.setValueAt(insertionIndex, valueToInsert);
41	    }
42	
43	    private static int findInsertionIndex(IntArraySlice slice, int currentIndex, int valueToInsert) {
44	        int scanIndex = currentIndex - 1;
45	
46	        while (scanIndex >= slice.startInclusive() && slice.valueAt(scanIndex) > valueToInsert) {
47	            scanIndex--;
48	        }
49	
50	        return scanIndex + 1;
51	    }
52	}

